//! Port of `tests/test_crypto.py`, plus golden Fernet vectors generated by the
//! real Python `cryptography` implementation (`fixtures/crypto_golden.json`).

use aimap::crypto::{generate_key, Cipher, CryptoError};

fn is_crypto_error(e: &CryptoError, needle: &str) -> bool {
    e.0.contains(needle)
}

#[test]
fn roundtrip_and_no_plaintext() {
    let c = Cipher::new(&generate_key()).unwrap();
    let token = c.encrypt("me@x.com", "s3cret");
    assert!(!token.contains("s3cret") && !token.contains("me@x.com"));
    assert_eq!(c.decrypt("me@x.com", &token).unwrap(), "s3cret");
    assert_eq!(format!("{:?}", c), "Cipher(<redacted>)");
}

#[test]
fn token_bound_to_user() {
    let c = Cipher::new(&generate_key()).unwrap();
    let token = c.encrypt("a@x.com", "pw");
    let e = c.decrypt("b@x.com", &token).unwrap_err();
    assert!(is_crypto_error(&e, "different account"));
}

#[test]
fn wrong_key_rejected() {
    let token = Cipher::new(&generate_key()).unwrap().encrypt("a", "pw");
    let c = Cipher::new(&generate_key()).unwrap();
    let e = c.decrypt("a", &token).unwrap_err();
    assert!(is_crypto_error(&e, "wrong key"));
}

#[test]
fn rotation() {
    let old = generate_key();
    let new = generate_key();
    let token = Cipher::new(&old).unwrap().encrypt("a", "pw");
    let both = Cipher::new(&format!("{new}, {old}")).unwrap();
    assert_eq!(both.decrypt("a", &token).unwrap(), "pw");
    let rotated = both.rotate(&token).unwrap();
    assert_eq!(Cipher::new(&new).unwrap().decrypt("a", &rotated).unwrap(), "pw");
    assert!(Cipher::new(&old).unwrap().decrypt("a", &rotated).is_err());
}

#[test]
fn bad_keys() {
    for key in ["", " , ", "not-a-key"] {
        assert!(Cipher::new(key).is_err(), "key {key:?} should be rejected");
    }
}

#[test]
fn golden_python_tokens() {
    let golden: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/tests/fixtures/crypto_golden.json"
        ))
        .unwrap(),
    )
    .unwrap();
    for case in golden["cases"].as_array().unwrap() {
        let keys = case["keys"].as_array().unwrap();
        let cipher = Cipher::from_key_list(keys.iter().map(|k| k.as_str().unwrap()))
            .unwrap_or_else(|e| panic!("case {}: keys rejected: {}", case["name"], e));
        let result = cipher.decrypt(case["user"].as_str().unwrap(), case["token"].as_str().unwrap());
        match (result, case.get("expect_password"), case.get("expect_error")) {
            (Ok(pw), Some(expected), _) => {
                assert_eq!(pw, expected.as_str().unwrap(), "case {}", case["name"]);
            }
            (Err(e), _, Some(expected_err)) => {
                assert!(
                    e.0.contains(expected_err.as_str().unwrap()),
                    "case {}: {:?} missing {:?}",
                    case["name"],
                    e,
                    expected_err
                );
            }
            (other, _, _) => panic!("case {}: unexpected result {:?}", case["name"], other),
        }
    }
}

#[test]
fn rust_tokens_are_valid_fernet() {
    // Shape checks: the token format must stay Fernet (version byte 0x80,
    // timestamp + IV + ciphertext + HMAC, url-safe base64).
    let c = Cipher::new(&generate_key()).unwrap();
    let token = c.encrypt("u@x.com", "p");
    use base64::Engine;
    let raw = base64::engine::general_purpose::URL_SAFE_NO_PAD
        .decode(&token)
        .unwrap();
    assert_eq!(raw[0], 0x80);
    assert!(raw.len() > 57 + 16);
}
